def load(chunk_name):
    print(f&quot;Loading chunk {chunk_name}&quot;)
    return f&quot;chunk --- --- {chunk_name}&quot;


def sanitize(chunk):
    print(f&quot;Sanitizing chunk {chunk}&quot;)
    return chunk


def mean(chunks):
    print(f&quot;mean {chunks}&quot;)
    return chunks[0]


def save(result):
    print(&quot;saving result&quot;)

